package io.atlas.modules.market.repository;
import io.atlas.modules.database.DatabaseConfig;
import java.sql.*;import java.util.*;
public final class MarketRepository {
 public record Listing(UUID id,UUID seller,String sellerName,UUID buyer,String kind,UUID pokemon,String payload,String name,long price,String state,String credit,java.time.Instant expiresAt,String category,int flags,String serverName,int durationSeconds,String endReason){
  public Listing(UUID id,UUID seller,String sellerName,UUID buyer,String kind,UUID pokemon,String payload,String name,long price,String state,String credit){this(id,seller,sellerName,buyer,kind,pokemon,payload,name,price,state,credit,null,"UNKNOWN",-1,"Emerald",86400,null);}
 }
 public record Draft(UUID id,UUID seller,String sellerName,String kind,UUID pokemon,String payload,String name,long price,String category,int flags,String serverName,int durationSeconds){
  public Draft(UUID id,UUID seller,String sellerName,String kind,UUID pokemon,String payload,String name,long price){this(id,seller,sellerName,kind,pokemon,payload,name,price,"UNKNOWN",-1,"Emerald",86400);}
  public Draft price(long price){return new Draft(id,seller,sellerName,kind,pokemon,payload,name,price,category,flags,serverName,durationSeconds);}
  public Draft duration(int seconds){return new Draft(id,seller,sellerName,kind,pokemon,payload,name,price,category,flags,serverName,seconds);}
 }
 private Connection connect()throws SQLException{var p=new Properties();p.setProperty("user",DatabaseConfig.USER);p.setProperty("password",DatabaseConfig.PASSWORD);p.setProperty("connectTimeout","3");p.setProperty("socketTimeout","10");return DriverManager.getConnection(DatabaseConfig.jdbcUrl(),p);}
 private Listing row(ResultSet r)throws SQLException{return new Listing(r.getObject("id",UUID.class),r.getObject("seller",UUID.class),r.getString("seller_name"),r.getObject("buyer",UUID.class),r.getString("kind"),r.getObject("pokemon_uuid",UUID.class),r.getString("payload"),r.getString("name"),r.getLong("price"),r.getString("state"),r.getString("credit_state"),r.getTimestamp("expires_at")==null?null:r.getTimestamp("expires_at").toInstant(),r.getString("item_category"),r.getInt("pokemon_flags"),r.getString("server_name"),r.getInt("duration_seconds"),r.getString("end_reason"));}
 public Optional<Listing> find(UUID id){try(var c=connect();var p=c.prepareStatement("SELECT * FROM market_listings WHERE id=?")){p.setObject(1,id);try(var r=p.executeQuery()){return r.next()?Optional.of(row(r)):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean prepare(Draft draft,int limit){try(var c=connect()){c.setAutoCommit(false);try{try(var p=c.prepareStatement("SELECT pg_advisory_xact_lock(?)")){p.setLong(1,draft.seller().getMostSignificantBits());p.executeQuery().close();}try(var p=c.prepareStatement("SELECT count(*) FROM market_listings WHERE seller=? AND state NOT IN ('SOLD','CANCELLED','VOID')")){p.setObject(1,draft.seller());try(var r=p.executeQuery()){r.next();if(r.getInt(1)>=limit){c.rollback();return false;}}}try(var p=c.prepareStatement("INSERT INTO market_listings(id,seller,seller_name,kind,pokemon_uuid,payload,name,price,state,item_category,pokemon_flags,server_name,duration_seconds) VALUES(?,?,?,?,?,?::jsonb,?,?,'PREPARING',?,?,?,?) ON CONFLICT DO NOTHING")){p.setObject(1,draft.id());p.setObject(2,draft.seller());p.setString(3,draft.sellerName());p.setString(4,draft.kind());p.setObject(5,draft.pokemon());p.setString(6,draft.payload());p.setString(7,draft.name());p.setLong(8,draft.price());p.setString(9,draft.category());p.setInt(10,draft.flags());p.setString(11,draft.serverName());p.setInt(12,draft.durationSeconds());boolean inserted=p.executeUpdate()==1;c.commit();return inserted;}}catch(Exception e){c.rollback();throw e;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Listing> list(String kind,UUID owner,int page,String search){return list(io.atlas.modules.market.model.MarketBrowse.defaults(kind,owner!=null,page,search),owner);}
 public List<Listing> list(io.atlas.modules.market.model.MarketBrowse browse,UUID owner){
  var out=new ArrayList<Listing>();
  String query="SELECT * FROM market_listings WHERE (?='ALL' OR kind=?) AND "+(owner==null?"state='ACTIVE' AND expires_at>now() AND name ILIKE ?":"seller=? AND state<>'VOID'")+" AND (?='ALL' OR item_category=?) AND (?=0 OR (pokemon_flags>=0 AND (pokemon_flags & ?)=?)) ORDER BY "+browse.sort().sql+" LIMIT 28 OFFSET ?";
  try(var c=connect();var p=c.prepareStatement(query)){
   p.setString(1,browse.kind());p.setString(2,browse.kind());
   if(owner==null)p.setString(3,"%"+browse.search().replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%");else p.setObject(3,owner);
   p.setString(4,browse.itemFilter().name());p.setString(5,browse.itemFilter().name());p.setInt(6,browse.pokemonFilter().mask());p.setInt(7,browse.pokemonFilter().mask());p.setInt(8,browse.pokemonFilter().mask());p.setInt(9,browse.page()*27);
   try(var result=p.executeQuery()){while(result.next())out.add(row(result));}return out;
  }catch(SQLException e){throw new IllegalStateException(e);}
 }
 public List<Listing> unclassified(){var out=new ArrayList<Listing>();try(var c=connect();var p=c.prepareStatement("SELECT * FROM market_listings WHERE pokemon_flags=-1 OR item_category='UNKNOWN' LIMIT 50");var result=p.executeQuery()){while(result.next())out.add(row(result));return out;}catch(SQLException e){throw new IllegalStateException(e);}}
 public void classify(UUID id,String category,int flags){try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET item_category=?,pokemon_flags=? WHERE id=?")){p.setString(1,category);p.setInt(2,flags);p.setObject(3,id);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public int expire(){try(var init=connect();var statement=init.prepareStatement("UPDATE market_listings SET expires_at=now()+duration_seconds*interval '1 second' WHERE state='ACTIVE' AND expires_at IS NULL")){statement.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET state='CANCEL_REQUESTED',end_reason='EXPIRED',updated_at=now() WHERE state='ACTIVE' AND expires_at<=now()")){return p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Listing> pending(){var out=new ArrayList<Listing>();try(var c=connect();var p=c.prepareStatement("SELECT * FROM market_listings WHERE (state IN ('PREPARING','ESCROWING','DEBITING','PAYING','DEBITED','DELIVERING','CANCEL_REQUESTED','RETURNING') OR credit_state IN ('PENDING','PAYING')) AND EXISTS(SELECT 1 FROM players p WHERE p.is_online AND (p.uuid=market_listings.seller OR p.uuid=market_listings.buyer)) ORDER BY created_at LIMIT 100");var r=p.executeQuery()){while(r.next())out.add(row(r));return out;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean buy(UUID id,UUID buyer){try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET buyer=?,state='DEBITING' WHERE id=? AND state='ACTIVE' AND expires_at>now() AND seller<>?")){p.setObject(1,buyer);p.setObject(2,id);p.setObject(3,buyer);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean cancel(UUID id,UUID seller){try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET state='CANCEL_REQUESTED',end_reason='CANCELLED' WHERE id=? AND seller=? AND state='ACTIVE'")){p.setObject(1,id);p.setObject(2,seller);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean transition(UUID id,String from,String to){if(!Set.of("PREPARING","DEBITING","CANCEL_REQUESTED","ESCROWING","ACTIVE","VOID","PAYING","DEBITED","DELIVERING","SOLD","RETURNING","CANCELLED","REVIEW").contains(to))throw new IllegalArgumentException();try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET state=?,expires_at=CASE WHEN ?='ACTIVE' THEN COALESCE(expires_at,now()+duration_seconds*interval '1 second') ELSE expires_at END,buyer=CASE WHEN ?='ACTIVE' THEN NULL ELSE buyer END,credit_state=CASE WHEN ?='SOLD' THEN 'AVAILABLE' ELSE credit_state END,updated_at=now() WHERE id=? AND state=?")){p.setString(1,to);p.setString(2,to);p.setString(3,to);p.setString(4,to);p.setObject(5,id);p.setString(6,from);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean credit(UUID id,String from,String to){try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET credit_state=?,updated_at=now() WHERE id=? AND state='SOLD' AND credit_state=?")){p.setString(1,to);p.setObject(2,id);p.setString(3,from);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 public int withdraw(UUID seller,String kind){try(var c=connect();var p=c.prepareStatement("UPDATE market_listings SET credit_state='PENDING' WHERE seller=? AND (?='ALL' OR kind=?) AND state='SOLD' AND credit_state='AVAILABLE'")){p.setObject(1,seller);p.setString(2,kind);p.setString(3,kind);return p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}

}
